Create a module in lib/inputParser.js that:

1. Accepts JSON input from PRD-Parser
2. Validates the structure of the input
3. Extracts agent name, description, and requirements
4. Normalizes agent name for directory creation

```javascript
// lib/inputParser.js
const validateInput = (input) => {
  // Validate input has required fields
  if (!input.agentName || !input.tasks || !Array.isArray(input.tasks)) {
    throw new Error('Invalid input: missing required fields');
  }

  return true;
};

const parseInput = (input) => {
  validateInput(input);

  // Normalize agent name for directory (lowercase, hyphens instead of spaces)
  const normalizedAgentName = input.agentName.toLowerCase().replace(/\s+/g, '-');

  return {
    agentName: input.agentName,
    normalizedAgentName,
    description: input.description || '',
    tasks: input.tasks,
    // Extract other relevant metadata
    metadata: input.metadata || {}
  };
};

module.exports = { parseInput, validateInput };
```

