```javascript
// lib/fileGenerator.js
const fs = require('fs-extra');
const path = require('path');
const TemplateEngine = require('./templateEngine');

class FileGenerator {
  constructor(baseDir) {
    this.baseDir = baseDir || 'src';
    this.templateEngine = new TemplateEngine();
  }

  async createDirectoryStructure(agentName) {
    const agentDir = path.join(this.baseDir, agentName);

    // Create main directory and subdirectories
    await fs.ensureDir(agentDir);
    await fs.ensureDir(path.join(agentDir, 'config'));
    await fs.ensureDir(path.join(agentDir, 'templates'));
    await fs.ensureDir(path.join(agentDir, 'tests'));

    return agentDir;
  }

  async generateFile(agentDir, fileName, templateName, data) {
    try {
      const content = await this.templateEngine.render(templateName, data);
      const filePath = path.join(agentDir, fileName);
      await fs.writeFile(filePath, content, 'utf8');
      return filePath;
    } catch (error) {
      throw new Error(`Failed to generate ${fileName}: ${error.message}`);
    }
  }

  async generateAgentFiles(agentData) {
    const { normalizedAgentName } = agentData;
    const agentDir = await this.createDirectoryStructure(normalizedAgentName);

    // Generate standard files
    await this.generateFile(agentDir, 'main.js', 'main.js', agentData);
    await this.generateFile(agentDir, 'README.md', 'README.md', agentData);
    await this.generateFile(agentDir, 'package.json', 'package.json', agentData);
    await this.generateFile(path.join(agentDir, 'config'), 'default.json', 'config/default.json', agentData);

    return agentDir;
  }
}

module.exports = FileGenerator;
```

