```javascript
// lib/changelogUpdater.js
const fs = require('fs-extra');
const path = require('path');

class ChangelogUpdater {
  constructor(changelogPath) {
    this.changelogPath = changelogPath || path.join(process.cwd(), 'CHANGELOG.md');
  }

  async readChangelog() {
    try {
      if (await fs.pathExists(this.changelogPath)) {
        return await fs.readFile(this.changelogPath, 'utf8');
      }
      return '# Changelog\n\nAll notable changes to this project will be documented in this file.\n';
    } catch (error) {
      throw new Error(`Failed to read changelog: ${error.message}`);
    }
  }

  async updateChangelog(agentData) {
    try {
      let changelog = await this.readChangelog();

      // Get current date in YYYY-MM-DD format
      const date = new Date().toISOString().split('T')[0];

      // Create new entry
      const newEntry = `\n## [${agentData.agentName}] - ${date}\n\n### Added\n- Initial scaffold for ${agentData.agentName} agent\n- Basic functionality and configuration\n`;

      // Find position to insert (after the header)
      const headerEndPos = changelog.indexOf('\n\n');
      if (headerEndPos !== -1) {
        changelog = changelog.substring(0, headerEndPos + 2) + newEntry + changelog.substring(headerEndPos + 2);
      } else {
        changelog += newEntry;
      }

      // Write updated changelog
      await fs.writeFile(this.changelogPath, changelog, 'utf8');
      return true;
    } catch (error) {
      throw new Error(`Failed to update changelog: ${error.message}`);
    }
  }
}

module.exports = ChangelogUpdater;
```

Implement a naming convention validator in lib/namingValidator.js:

```javascript
// lib/namingValidator.js
class NamingValidator {
  constructor(options = {}) {
    this.options = {
      allowedPrefixes: options.allowedPrefixes || [],
      allowedSuffixes: options.allowedSuffixes || ['Agent', 'Service', 'Manager'],
      minLength: options.minLength || 3,
      maxLength: options.maxLength || 50,
      pattern: options.pattern || /^[a-zA-Z][a-zA-Z0-9-]*$/
    };
  }

  validateAgentName(name) {
    const errors = [];

    // Check length
    if (name.length < this.options.minLength) {
      errors.push(`Name is too short (minimum ${this.options.minLength} characters)`);
    }

    if (name.length > this.options.maxLength) {
      errors.push(`Name is too long (maximum ${this.options.maxLength} characters)`);
    }

    // Check pattern
    if (!this.options.pattern.test(name)) {
      errors.push('Name contains invalid characters (use letters, numbers, and hyphens only)');
    }

    // Check prefixes if specified
    if (this.options.allowedPrefixes.length > 0) {
      const hasValidPrefix = this.options.allowedPrefixes.some(prefix => name.startsWith(prefix));
      if (!hasValidPrefix) {
        errors.push(`Name must start with one of: ${this.options.allowedPrefixes.join(', ')}`);
      }
    }

    // Check suffixes if specified
    if (this.options.allowedSuffixes.length > 0) {
      const hasValidSuffix = this.options.allowedSuffixes.some(suffix => name.endsWith(suffix));
      if (!hasValidSuffix) {
        errors.push(`Name must end with one of: ${this.options.allowedSuffixes.join(', ')}`);
      }
    }

    return {
      isValid: errors.length === 0,
      errors
    };
  }

  suggestValidName(name) {
    // If name doesn't end with a valid suffix, add the first allowed suffix
    if (this.options.allowedSuffixes.length > 0) {
      const hasValidSuffix = this.options.allowedSuffixes.some(suffix => name.endsWith(suffix));
      if (!hasValidSuffix) {
        return `${name}${this.options.allowedSuffixes[0]}`;
      }
    }

    return name;
  }
}

module.exports = NamingValidator;
```

