Implement Git integration in lib/gitIntegration.js:

```javascript
// lib/gitIntegration.js
const { execSync } = require('child_process');
const path = require('path');

class GitIntegration {
  constructor(options = {}) {
    this.options = {
      commitMessage: options.commitMessage || 'feat: Generate scaffold for {agentName}',
      autoCommit: options.autoCommit !== undefined ? options.autoCommit : true
    };
  }

  isGitRepository() {
    try {
      execSync('git rev-parse --is-inside-work-tree', { stdio: 'ignore' });
      return true;
    } catch (error) {
      return false;
    }
  }

  getGitStatus() {
    try {
      return execSync('git status --porcelain').toString().trim();
    } catch (error) {
      throw new Error(`Failed to get Git status: ${error.message}`);
    }
  }

  addFiles(agentDir) {
    try {
      execSync(`git add ${agentDir}`, { stdio: 'ignore' });
      // Also add CHANGELOG.md if it exists
      execSync('git add CHANGELOG.md', { stdio: 'ignore' });
      return true;
    } catch (error) {
      throw new Error(`Failed to add files to Git: ${error.message}`);
    }
  }

  commit(agentData) {
    try {
      const message = this.options.commitMessage.replace('{agentName}', agentData.agentName);
      execSync(`git commit -m "${message}"`, { stdio: 'ignore' });
      return true;
    } catch (error) {
      throw new Error(`Failed to commit changes: ${error.message}`);
    }
  }

  async handleGitOperations(agentData, agentDir) {
    if (!this.isGitRepository()) {
      console.log('Not a Git repository, skipping Git operations');
      return false;
    }

    const status = this.getGitStatus();
    if (!status) {
      console.log('No changes to commit');
      return false;
    }

    this.addFiles(agentDir);

    if (this.options.autoCommit) {
      this.commit(agentData);
      console.log(`Changes committed with message: ${this.options.commitMessage.replace('{agentName}', agentData.agentName)}`);
    } else {
      console.log('Changes staged for commit');
    }

    return true;
  }
}

module.exports = GitIntegration;
```

